// ===== SETTINGS: Configure platforms and account IDs below =====
const LIVE = {
  linkedin: true,
  facebook: true,
  instagram: true,
  twitter: true,
};
const CONFIG = {
  linkedin_author: 'urn:li:person:YOUR_LINKEDIN_AUTHOR_ID',
  fb_page_id: 'YOUR_FACEBOOK_PAGE_ID',
  ig_user_id: 'YOUR_INSTAGRAM_USER_ID',
};
// =============================================

// Session State Tracking for Approval Gate (Security Fix #1)
const staticData = $getWorkflowStaticData('global');
staticData.sessions = staticData.sessions || {};

let sessionId = 'default';
try {
  sessionId = $('When chat message received').first().json.sessionId || 'default';
} catch (e) {}

const currentSession = staticData.sessions[sessionId] || { lastStatus: null, turnCount: 0 };
currentSession.turnCount += 1;

// SECURITY FIX #5: Anti-Code Generation Hard Gate
function containsCode(text) {
  if (typeof text !== 'string' || !text.trim()) return false;
  const codePatterns = [
    /```[a-zA-Z0-9]*/,                                        // Markdown code blocks
    /<\/?script\b/i,                                         // <script> tags
    /<\/?html\b/i,                                           // <html> tags
    /\b(function\s*\(|def\s+\w+\s*\(|class\s+\w+|import\s+\w+\s+from|from\s+\w+\s+import)/i, // Functions/Classes/Imports
    /\b(const|let|var)\s+\w+\s*=/,                           // JS variables
    /\b(console\.log|print\(|eval\(|exec\()/i,               // Console/Print/Eval statements
    /\b(SELECT\s+.+?\s+FROM|INSERT\s+INTO|UPDATE\s+.+?\s+SET)/i, // SQL queries
    /#!(?:\/usr\/bin|\/bin)\/(?:bash|sh|python|perl|node)/i, // Hashbangs
    /\b(curl|wget|chmod|chown|sudo)\s+-[a-zA-Z]/i            // CLI commands
  ];
  return codePatterns.some(pattern => pattern.test(text));
}

// Removes literal "\n", emoji, markdown symbols and hashtags from any text
function clean(text) {
  if (typeof text !== 'string') return text;
  let t = text;
  t = t.replace(/\\n/g, '\n');                 // literal backslash-n -> real line break
  t = t.replace(/\*\*/g, '').replace(/\*/g, ''); // markdown bold/italic
  t = t.replace(/^#+\s*/gm, '');                 // markdown headers
  t = t.replace(/#[\w-]+/g, '');                 // hashtags like #Rust
  t = t.replace(/[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}\u{2190}-\u{21FF}\u{2B00}-\u{2BFF}]/gu, ''); // emoji
  t = t.replace(/[ \t]+\n/g, '\n');               // trailing spaces before line breaks
  t = t.replace(/\n{3,}/g, '\n\n');               // no more than one blank line
  t = t.trim();
  return t;
}

let out = $json.output;
if (typeof out === 'string') {
  try { out = JSON.parse(out); }
  catch (e) { out = { status: 'needs_info', message_to_user: out }; }
}
out = { ...out };
out.platforms = Array.isArray(out.platforms) ? out.platforms : [];
out.posts = out.posts && typeof out.posts === 'object' ? out.posts : {};
out.image_url = out.image_url || '';
out.message_to_user = out.message_to_user || 'Something went wrong. Please try again.';

// Hard Check for Code Generation
const rawMsg = String($json.output?.message_to_user || out.message_to_user || '');
const postTexts = Object.values(out.posts).join(' ');
const isCodeViolation = containsCode(rawMsg) || containsCode(postTexts);

if (isCodeViolation) {
  out.status = 'needs_info';
  out.posts = {};
  out.platforms = [];
  out.image_url = '';
  out.message_to_user = 'I am exclusively configured to draft social media posts for blog promotion. I cannot generate code or scripts. Please provide a blog post URL to get started.';
} else {
  out.message_to_user = clean(out.message_to_user);
  for (const k of Object.keys(out.posts)) out.posts[k] = clean(out.posts[k]);
}

// SECURITY FIX #1: Deterministic Code-Level Approval Invariant
const stateSecurityOverride = (out.status === 'approved') && 
  (currentSession.turnCount <= 1 || currentSession.lastStatus !== 'draft_ready');

if (stateSecurityOverride) {
  out.status = 'draft_ready';
  out.message_to_user = (out.message_to_user || '') + '\n\n[Security Check] Drafts generated. Please review and confirm to publish.';
}

const problems = [];
if (out.status === 'approved') {
  if (!out.platforms.length) problems.push('No platform is selected.');
  for (const p of out.platforms) {
    if (!String(out.posts[p] || '').trim()) problems.push(`${p}: the post text is empty.`);
  }
  if (out.platforms.includes('twitter') && out.posts.twitter) {
    const len = out.posts.twitter.replace(/https?:\/\/\S+/g, 'x'.repeat(23)).length;
    if (len > 280) problems.push(`X post is ${len}/280 characters.`);
  }
  if (out.platforms.includes('linkedin') && (out.posts.linkedin || '').length > 3000) problems.push('LinkedIn post is over 3000 characters.');
  if (out.platforms.includes('instagram') && (out.posts.instagram || '').length > 2200) problems.push('Instagram caption is over 2200 characters.');
  if (out.platforms.includes('facebook') && !String(out.image_url || '').trim()) {
    problems.push('Facebook featured image URL is missing. Provide a direct public JPEG or PNG image URL.');
  }
  if (problems.length) {
    out.status = 'draft_ready';
    out.message_to_user = 'I could not publish yet. ' + problems.join(' ') + ' Tell me how to fix it and I will update the drafts.';
  }
}

// Update last status stored in session static memory
currentSession.lastStatus = out.status;
staticData.sessions[sessionId] = currentSession;

return [{ json: { output: out, live: LIVE, config: CONFIG, problems, sessionSecurity: { turnCount: currentSession.turnCount, overridden: stateSecurityOverride, codeBlocked: isCodeViolation } } }];

const v = $('Validate Output').first().json;

const rows = $input.all()
  .map(i => i.json)
  .filter(r => r && (r.platform || r.error))   // Keep error-only items; do not discard them
  .map(r => ({
    platform: r.platform || 'Unknown',
    status: r.status || (r.error ? 'FAILED: ' + (typeof r.error === 'string' ? r.error : 'unknown error') : 'unknown'),
  }))
  .filter(r => r.status !== 'not_selected');

const icon = (s) => {
  s = String(s || '');
  if (s.startsWith('published')) return '✅';
  if (s.startsWith('FAILED')) return '❌';
  return '⚠️';
};

let text = (v.output.message_to_user || 'Publishing...') + '\n\nUpdate on your posts:\n' +
  rows.map(r => `${icon(r.status)} ${r.platform}: ${r.status}`).join('\n');

const anyDry = Object.entries(v.live || {}).some(([k, val]) => !val && v.output.platforms.includes(k));
if (anyDry) text += '\n\n(Some platforms are still in test mode: nothing was really posted for them. Flip LIVE.<platform> to true in "Validate Output" to go live.)';

return [{ json: { output: text } }];
